function spawn(){let type;let r=Math.random();if(r<.43)type='coin';else if(r<.49)type='gem';else if(r<.57)type='power';else if(r<.79)type=worlds[world].obstacle;else type=world===0?'mushroom':world===1?'drone':world===2?'rock':world===3?'icicle':'pillar';let obj={type,x:W+20,y:ground-13,v:0,phase:Math.random()*7,hit:false};if(type==='coin'||type==='gem'){obj.y=ground-rnd(36,94);obj.rad=type==='gem'?5:4}else if(type==='power'){obj.y=ground-rnd(45,76);obj.power=pick(['shield','magnet','boost'])}else if(type==='drone'){obj.y=ground-52-rnd(0,20)}else if(type==='icicle'){obj.y=ground-52}else if(type==='flame'){obj.y=ground-9}else if(type==='pillar'){obj.y=ground-36}else if(type==='rock'){obj.y=ground-12}else if(type==='mushroom'){obj.y=ground-15}else if(type==='stump'){obj.y=ground-11}run.objects.push(obj)}
function emit(x,y,color,n=8,power=2){for(let i=0;i<n;i++)run.particles.push({x,y,vx:rnd(-power,power),vy:rnd(-power*1.5,power*.3),life:rnd(18,38),max:38,color,size:Math.random()<.25?2:1})}
function drawObjects(dt){for(let i=run.objects.length-1;i>=0;i--){let o=run.objects[i];o.x-=run.speed*(o.type==='coin'||o.type==='gem'?1:1);o.phase+=dt*.008;let x=Math.round(o.x),y=Math.round(o.y+Math.sin(o.phase)*2);const w=worlds[world];if(o.type==='coin'||o.type==='gem'){ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(o.phase)*.18);ctx.fillStyle=o.type==='gem'?'#86f3e7':'#ffd56d';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=10;ctx.fillRect(-o.rad,-o.rad,o.rad*2,o.rad*2);ctx.shadowBlur=0;ctx.fillStyle='#fff7ce';ctx.fillRect(-1,-o.rad+1,2,2);ctx.fillStyle=o.type==='gem'?'#43abb1':'#d99b43';ctx.fillRect(-o.rad+1,1,o.rad*2-2,2);ctx.restore();if(Math.abs(x-90)<16&&Math.abs(y-(run.jump?ground-27-run.jump:ground-19))<26){o.hit=true;run.coins+=o.type==='gem'?5:1;run.score+=o.type==='gem'?100:30;run.combo++;run.comboTime=150;if(o.type==='gem')run.gem++;emit(x,y,o.type==='gem'?'#7ff1e1':'#ffdc76',9,2);run.objects.splice(i,1);continue}}
else if(o.type==='power'){ctx.fillStyle='#a1f2cf';ctx.shadowColor='#9ef3ce';ctx.shadowBlur=11;ctx.fillRect(x-7,y-7,14,14);ctx.shadowBlur=0;ctx.fillStyle='#183d42';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText(o.power==='shield'?'✧':o.power==='magnet'?'⌁':'➤',x,y+3);if(Math.abs(x-90)<15&&Math.abs(y-(ground-20-run.jump))<27){run.shield=360;run.invuln=180;emit(x,y,'#b3ffdd',18,3);showToast(o.power==='shield'?'Aegis power-up!':o.power==='magnet'?'Spark magnet!':'Swift boost!');if(o.power==='boost')run.speed+=.5;run.objects.splice(i,1);continue}}
else{let hitX=Math.abs(x-90)<16,low=run.slide>0||run.jump>25,hitY=o.type==='drone'||o.type==='icicle'?Math.abs(y-(ground-30))<37:Math.abs(y-ground)<22;ctx.save();if(o.type==='stump'||o.type==='rock'||o.type==='pillar'){ctx.fillStyle=o.type==='stump'?'#b4774d':o.type==='rock'?'#bd6557':'#aa9b76';ctx.fillRect(x-9,y-13,18,14);ctx.fillStyle=o.type==='stump'?'#dca46a':o.type==='rock'?'#ed8871':'#d4c398';ctx.fillRect(x-11,y-15,22,4);ctx.fillStyle='#382e37';ctx.fillRect(x-4,y-8,3,2);ctx.fillRect(x+3,y-8,3,2)}else if(o.type==='mushroom'){ctx.fillStyle='#e07462';ctx.fillRect(x-11,y-12,22,7);ctx.fillStyle='#fff0d6';ctx.fillRect(x-6,y-9,3,2);ctx.fillRect(x+3,y-7,3,2);ctx.fillStyle='#ead2a4';ctx.fillRect(x-5,y-5,10,7)}else if(o.type==='drone'){ctx.fillStyle='#ed8fc9';ctx.fillRect(x-11,y-5,22,9);ctx.fillStyle='#82edf0';ctx.fillRect(x-5,y-2,5,3);ctx.fillRect(x-15,y-9,7,2);ctx.fillRect(x+8,y-9,7,2)}else if(o.type==='flame'){ctx.fillStyle='#ff724e';ctx.fillRect(x-8,y-12,16,12);ctx.fillStyle='#ffc45d';ctx.fillRect(x-4,y-8,8,8)}else if(o.type==='icicle'){ctx.fillStyle='#9eeaf0';ctx.fillRect(x-5,y-18,10,18);ctx.fillStyle='#e9ffff';ctx.fillRect(x-3,y-17,3,10)}else{ctx.fillStyle='#e45f55';ctx.fillRect(x-8,y-9,16,9);ctx.fillStyle='#ffbb69';ctx.fillRect(x-4,y-14,8,5)}ctx.restore();if(hitX&&hitY&&!low&&run.invuln<=0&&!o.hit){o.hit=true;if(run.shield>0){run.shield=0;run.invuln=100;emit(90,ground-20,'#a9f3dc',24,4);showToast('Shield absorbed the hit!')}else{run.lives--;run.invuln=115;run.shake=12;run.combo=0;emit(90,ground-18,'#ff867d',15,3);if(run.lives<=0){run.objects.splice(i,1);endRun();return}}}}
if(x<-30)run.objects.splice(i,1)}
// particles
for(let i=run.particles.length-1;i>=0;i--){let p=run.particles[i];p.x+=p.vx-run.speed*.1;p.y+=p.vy;p.vy+=.06;p.life--;ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(Math.round(p.x),Math.round(p.y),p.size,p.size);if(p.life<=0)run.particles.splice(i,1)}ctx.globalAlpha=1}
let spawnTimer=70;
function startRun(){hero=save.selected;world=save.world;run={distance:0,coins:0,lives:3,speed:2.5,jump:0,vy:0,slide:0,skill:0,invuln:0,shield:0,combo:0,comboTime:0,objects:[],particles:[],bg:0, boss:0,bossHealth:100,shake:0,flash:0,score:0,gem:0};run.speed+=save.upgrades.boost*.14;spawnTimer=50;state='playing';document.querySelector('#home').style.display='none';document.querySelector('#worldSelector').style.display='none';document.querySelector('.footer').style.display='none';document.querySelector('#hud').classList.add('active');document.querySelectorAll('.screen').forEach(e=>e.classList.remove('show'));document.querySelector('#bossLabel').classList.remove('active');document.querySelector('#bossBar').classList.remove('active');last=performance.now();requestAnimationFrame(loop)}
function jump(){if(state!=='playing')return;if(run.jump===0){run.vy=9.7;run.jump=1;emit(90,ground-4,worlds[world].accent,5,1.3)}else if(run.jump===1){run.vy=8.1;run.jump=2;emit(90,ground-26,heroes[hero].color,9,2)}else return}
function slide(){if(state==='playing'){run.slide=34;emit(90,ground-5,'#c7d5d6',4,1)}}
function useSkill(){if(state!=='playing'||run.skill>0)return;run.skill=500;run.invuln=110;let name=heroes[hero].skill;run.flash=12;run.shake=4;
if(hero===0){run.speed+=1.3;run.objects.forEach(o=>{if(['coin','gem','power'].includes(o.type))return;if(o.x>55&&o.x<250){o.x=-100;emit(o.x,ground-16,'#ff995d',7,2)}});emit(90,ground-18,'#ff9b59',25,5)}else if(hero===1){run.objects.forEach(o=>{if(o.type==='coin'||o.type==='gem')o.x-=48});emit(90,ground-20,'#b7bfff',24,3)}else if(hero===2){run.speed+=.4;run.objects.forEach(o=>{if(!['coin','gem','power'].includes(o.type)&&o.x>60&&o.x<260)o.x=-100});emit(90,ground-20,'#8beac9',30,4)}else if(hero===3){run.invuln=240;emit(90,ground-20,'#bc90e3',22,3)}else if(hero===4){run.shield=240;run.lives=Math.min(3,run.lives+1);emit(90,ground-20,'#ffe79c',28,3)}else{run.objects.forEach(o=>{if(!['coin','gem','power'].includes(o.type)&&o.x<360){o.x=-100;emit(o.x,ground-15,'#9bdeff',10,3)}});run.score+=250;emit(90,ground-20,'#a0e9ff',30,5)}showToast(name+'!');}
function loop(now){if(state!=='playing')return;let dt=Math.min(34,now-last);last=now;let f=dt/16.67;run.distance+=run.speed*.075*f;run.score+=run.speed*.4*f;run.bg+=run.speed*f;run.speed=Math.min(5.5,2.5+run.distance*.0009);if(run.jump){run.vy-=.53*f;run.jump+=run.vy*f;if(run.jump<=0){run.jump=0;run.vy=0;emit(90,ground-3,worlds[world].accent,4,1)}}if(run.slide>0)run.slide-=f;if(run.skill>0)run.skill-=f;if(run.invuln>0)run.invuln-=f;if(run.shield>0)run.shield-=f;if(run.comboTime>0)run.comboTime-=f;else run.combo=0;run.boss+=f;if(run.boss>1050){run.boss=0;run.bossHealth=100;document.querySelector('#bossLabel').classList.add('active');document.querySelector('#bossBar').classList.add('active');showToast('Something stirs behind you...');setTimeout(()=>{if(state==='playing'){document.querySelector('#bossLabel').classList.remove('active');document.querySelector('#bossBar').classList.remove('active')}},7500)}if(run.bossHealth<100)run.bossHealth=Math.min(100,run.bossHealth+.04*f);spawnTimer-=f;if(spawnTimer<=0){spawn();spawnTimer=Math.max(36,rnd(58,100)-run.distance*.012)}if(run.shake>0)run.shake*=.78;
ctx.save();if(run.shake>1)ctx.translate(rnd(-run.shake,run.shake),rnd(-run.shake*.5,run.shake*.5));drawBackground(now);drawObjects(dt);let py=ground-18-run.jump;drawHero(ctx,90,py,1,hero,run.slide>0?'slide':run.jump>0?'jump':'run',now/1000);if(run.shield>0){ctx.strokeStyle='#b8f5de88';ctx.lineWidth=1;ctx.beginPath();ctx.arc(90,py,22+Math.sin(now*.01)*2,0,7);ctx.stroke()}if(run.flash>0){ctx.fillStyle=heroes[hero].color+'26';ctx.fillRect(0,0,W,H);run.flash--}ctx.restore();
const displayCoins=run.coins*(1+Math.min(run.combo,10)*.1);document.querySelector('#score').textContent=String(Math.floor(run.score+displayCoins*20)).padStart(5,'0');document.querySelector('#runCoins').textContent=String(run.coins).padStart(2,'0');document.querySelector('#lives').textContent=Array.from({length:3},(_,i)=>i<run.lives?'♥':'♡').join(' ');document.querySelector('#progress').style.width=(run.distance%1000)/10+'%';document.querySelector('#skillBtn').style.opacity=run.skill>0?'.48':'1';document.querySelector('#skillBtn').innerHTML=run.skill>0?'<small>⌛</small>'+Math.ceil(run.skill/60):'<small>✦</small>SKILL';if(run.distance%230<2)document.querySelector('#hudWorld').textContent=worlds[world].name+'  /  '+String(Math.floor(run.distance/230)+1).padStart(2,'0');requestAnimationFrame(loop)}
function endRun(){if(state!=='playing')return;state='result';let distance=Math.floor(run.distance),total=Math.floor(run.coins*(1+Math.min(run.combo,10)*.1));save.coins+=total;save.gems+=run.gem;save.totalCoins+=total;save.runs++;save.best=Math.max(save.best,distance);persist();document.querySelector('#resultDistance').textContent=distance;document.querySelector('#resultCoins').textContent=total;document.querySelector('#resultBest').textContent=save.best;document.querySelector('#resultText').textContent=distance>save.best-1?'A new high score. The forest remembers your name.':'Every spark brings the forest closer to waking.';document.querySelector('#resultKicker').textContent=distance>=save.best?'NEW PERSONAL BEST':'THE NIGHT CAUGHT UP';document.querySelector('#resultTitle').textContent=distance>500?'A legend in the making.':'A brave little run.';document.querySelector('#hud').classList.remove('active');document.querySelector('#resultScreen').classList.add('show');checkAchievements()}
function pause(){if(state==='playing'){state='paused';document.querySelector('#pauseScreen').classList.add('show')}}function resume(){state='playing';document.querySelector('#pauseScreen').classList.remove('show');last=performance.now();requestAnimationFrame(loop)}

function showToast(msg){let el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),1700)}
function checkAchievements(){let unlocked=null;if(save.totalCoins>=25&&!save.achievements.includes('first')){unlocked=['First Light','Collect 25 sparks.'];save.achievements.push('first')}else if(save.best>=500&&!save.achievements.includes('distance')){unlocked=['Into the Wild','Run 500 metres in a single run.'];save.achievements.push('distance')}else if(save.runs>=5&&!save.achievements.includes('runner')){unlocked=['Born to Run','Complete five runs.'];save.achievements.push('runner')}if(unlocked){document.querySelector('#achieveTitle').textContent=unlocked[0];document.querySelector('#achieveDesc').textContent=unlocked[1];document.querySelector('#achieveScreen').classList.add('show');persist()}}
function openScreen(id){document.querySelectorAll('.screen').forEach(e=>e.classList.remove('show'));document.querySelector('#'+id).classList.add('show')}
function renderCharacters(){let root=document.querySelector('#characterCards');root.innerHTML='';heroes.forEach((h,i)=>{let card=document.createElement('button');card.className='character-card'+(hero===i?' selected':'')+(save.unlocked.includes(i)?'':' locked');let stats=h.stats.map((_,n)=>`<i class="${n<h.stats[0]?'on':''}"></i>`).join('');card.innerHTML=`<canvas class="char-swatch" width="72" height="100"></canvas><div class="char-name">${h.name}</div><div class="char-role">${h.title} &nbsp;·&nbsp; ${h.passive}</div><div class="statline">${stats}</div><div class="char-skill">✦ &nbsp; ${h.skill}</div>${save.unlocked.includes(i)?'':`<div class="char-lock">✦ &nbsp; ${h.unlock} SPARKS</div>`}`;card.onclick=()=>{if(!save.unlocked.includes(i)){if(save.coins>=h.unlock){save.coins-=h.unlock;save.unlocked.push(i);showToast(h.name+' unlocked!');persist();renderCharacters()}else showToast('Need '+h.unlock+' sparks to unlock');return}hero=i;save.selected=i;persist();renderCharacters()};root.append(card);drawHeroPortrait(card.querySelector('canvas').getContext('2d'),i)});}
function renderUpgrades(){let upgrades=[['magnet','⌁','Spark magnet','Coins drift toward you from a little farther away.',90],['shield','✧','Second chance','Start each run with a protective ward.',140],['boost','➤','Fleet feet','Begin every run with a little extra speed.',180]];let root=document.querySelector('#upgradeGrid');root.innerHTML='';upgrades.forEach(([key,icon,title,desc,cost])=>{let level=save.upgrades[key]||0;let price=cost*(level+1);let div=document.createElement('div');div.className='upgrade';div.innerHTML=`<div class="upgrade-icon">${icon}</div><b>${title} <span style="color:#a7e7cf;font:9px 'DM Mono'">LV ${level}</span></b><p>${desc}</p><button class="buy" ${save.coins<price?'disabled':''}>UPGRADE &nbsp;·&nbsp; ✦ ${price}</button>`;div.querySelector('button').onclick=()=>{if(save.coins<price)return;save.coins-=price;save.upgrades[key]=level+1;persist();renderUpgrades();showToast(title+' upgraded!')};root.append(div)})}
function renderMissions(){let missions=[['Gather 25 sparks','Pick up coins across all your runs.','✦ 50',save.totalCoins>=25],['Run 500 metres','Cover 500 metres in a single run.','✦ 80',save.best>=500],['Five little adventures','Complete five runs.','◇ 10',save.runs>=5],['Find your first gem','Discover a rare moonstone on the trail.','✦ 60',save.gems>0]];let root=document.querySelector('#missionList');root.innerHTML='';missions.forEach((m,i)=>{let el=document.createElement('div');el.className='mission';el.innerHTML=`<div><b>${m[0]} ${m[3]?'✓':''}</b><small>${m[1]}</small></div><div class="mission-reward">${m[3]?'CLAIMED':m[2]}</div>`;if(m[3]&&!save.achievements.includes('mission'+i)){el.style.cursor='pointer';el.onclick=()=>{save.achievements.push('mission'+i);if(m[2].includes('50'))save.coins+=50;else if(m[2].includes('80'))save.coins+=80;else if(m[2].includes('10'))save.gems+=10;else save.coins+=60;persist();renderMissions();showToast('Mission reward claimed!')}}root.append(el)});document.querySelector('#highScore').textContent=save.best+' M'}
document.querySelector('#playBtn').onclick=startRun;document.querySelector('#heroesBtn').onclick=()=>{hero=save.selected;renderCharacters();openScreen('characterScreen')};document.querySelector('#selectPlay').onclick=startRun;document.querySelector('#pauseBtn').onclick=pause;document.querySelector('#resumeBtn').onclick=resume;document.querySelector('#quitBtn').onclick=endRun;document.querySelector('#againBtn').onclick=startRun;document.querySelector('#menuBtn').onclick=()=>{document.querySelectorAll('.screen').forEach(e=>e.classList.remove('show'));state='menu';document.querySelector('#home').style.display='flex';document.querySelector('#worldSelector').style.display='block';document.querySelector('.footer').style.display='flex';document.querySelector('#hud').classList.remove('active');updateHeroVisual()};document.querySelector('#skillBtn').onclick=useSkill;document.querySelector('#jumpBtn').onpointerdown=e=>{e.preventDefault();jump()};document.querySelector('#slideBtn').onpointerdown=e=>{e.preventDefault();slide()};document.querySelector('#soundBtn').onclick=()=>{sound=!sound;document.querySelector('#soundBtn').textContent=sound?'♫':'♪';showToast(sound?'Sound on':'Sound off')};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('.screen').classList.remove('show'));
document.querySelector('#app').addEventListener('click',e=>{if(e.target===document.querySelector('#worldName'))setWorld(world+1)});
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW')jump();if(e.code==='ArrowDown'||e.code==='KeyS')slide();if(e.code==='KeyX'||e.code==='ShiftLeft'||e.code==='KeyZ')useSkill();if(e.code==='Escape'||e.code==='KeyP'){if(state==='playing')pause();else if(state==='paused')resume()}if(state==='menu'&&e.code==='Enter')startRun()});window.addEventListener('keyup',e=>{keys[e.code]=false});
// Canvas stays at a small logical resolution; CSS scaling gives sharp pixel art.
function resize(){let dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=480;canvas.height=270;canvas.style.imageRendering='pixelated';ctx.imageSmoothingEnabled=false}window.addEventListener('resize',resize);resize();
function idleFrame(now){if(state==='playing')return;drawBackground(now);if(state==='menu'){let x=88,y=ground-18;drawHero(ctx,x,y,1,hero,'run',now/1000);for(let i=0;i<5;i++){let px=(i*93-now*.03)%W;ctx.fillStyle='#ffdc8caa';ctx.fillRect(px,ground-20-(i*17)%65,2,2)}}else if(state==='paused'){drawHero(ctx,90,ground-18,1,hero,'run',now/1000)}requestAnimationFrame(idleFrame)}requestAnimationFrame(idleFrame);
// Intro background/menu idle. The game loop renders continuously after starting.
})();
</script></body></html>

