function drawObjects(dt){for(let i=run.objects.length-1;i>=0;i--){let o=run.objects[i];o.x-=run.speed;o.phase+=dt*.008;let x=Math.round(o.x),y=Math.round(o.y+Math.sin(o.phase)*2),accent=worlds[world][6];if(o.type==='coin'||o.type==='gem'){c.save();c.translate(x,y);c.rotate(Math.sin(o.phase)*.18);c.fillStyle=o.type==='gem'?'#86f3e7':'#ffd56d';c.shadowColor=c.fillStyle;c.shadowBlur=10;c.fillRect(-4,-4,8,8);c.shadowBlur=0;c.fillStyle='#fff7ce';c.fillRect(-1,-3,2,2);c.restore();if(Math.abs(x-90)<15&&Math.abs(y-(G-19-run.jump))<27){run.coins+=o.type==='gem'?5:1;run.score+=o.type==='gem'?100:30;run.combo++;run.comboTime=150;if(o.type==='gem')run.gem++;emit(x,y,o.type==='gem'?'#7ff1e1':'#ffdc76',9,2);run.objects.splice(i,1);continue}}else if(o.type==='power'){c.fillStyle='#a1f2cf';c.shadowColor='#9ef3ce';c.shadowBlur=10;c.fillRect(x-7,y-7,14,14);c.shadowBlur=0;c.fillStyle='#183d42';c.font='bold 10px sans-serif';c.textAlign='center';c.fillText('✧',x,y+3);if(Math.abs(x-90)<15&&Math.abs(y-(G-20-run.jump))<27){run.shield=360;run.invuln=180;if(o.power==='boost')run.speed+=.5;emit(x,y,'#b3ffdd',18,3);toast(o.power+' power-up!');run.objects.splice(i,1);continue}}else{let low=run.slide>0||run.jump>25,hitY=(o.type==='drone'||o.type==='icicle')?Math.abs(y-(G-30))<37:Math.abs(y-G)<22;c.save();if(o.type==='drone'){c.fillStyle='#ed8fc9';c.fillRect(x-11,y-5,22,9);c.fillStyle='#82edf0';c.fillRect(x-5,y-2,5,3);c.fillRect(x-15,y-9,7,2);c.fillRect(x+8,y-9,7,2)}else if(o.type==='icicle'){c.fillStyle='#9eeaf0';c.fillRect(x-5,y-18,10,18);c.fillStyle='#e9ffff';c.fillRect(x-3,y-17,3,10)}else if(o.type==='flame'){c.fillStyle='#ff724e';c.fillRect(x-8,y-12,16,12);c.fillStyle='#ffc45d';c.fillRect(x-4,y-8,8,8)}else if(o.type==='mushroom'){c.fillStyle='#e07462';c.fillRect(x-11,y-12,22,7);c.fillStyle='#fff0d6';c.fillRect(x-6,y-9,3,2);c.fillRect(x+3,y-7,3,2);c.fillStyle='#ead2a4';c.fillRect(x-5,y-5,10,7)}else{c.fillStyle=o.type==='rock'?'#bd6557':accent;c.fillRect(x-9,y-13,18,14);c.fillStyle='#f4d0a1';c.fillRect(x-11,y-15,22,4);c.fillStyle='#372f39';c.fillRect(x-4,y-8,3,2);c.fillRect(x+3,y-8,3,2)}c.restore();if(Math.abs(x-90)<16&&hitY&&!low&&run.invuln<=0&&!o.hit){o.hit=true;if(run.shield>0){run.shield=0;run.invuln=100;emit(90,G-20,'#a9f3dc',24,4);toast('Shield absorbed the hit!')}else{run.lives--;run.invuln=115;run.shake=12;run.combo=0;emit(90,G-18,'#ff867d',15,3);if(run.lives<=0){endRun();return}}}}if(x<-30)run.objects.splice(i,1)}for(let i=run.particles.length-1;i>=0;i--){let p=run.particles[i];p.x+=p.vx-run.speed*.1;p.y+=p.vy;p.vy+=.06;p.life--;c.globalAlpha=Math.max(0,p.life/38);c.fillStyle=p.color;c.fillRect(p.x,p.y,p.size,p.size);if(p.life<=0)run.particles.splice(i,1)}c.globalAlpha=1}
function start(){hero=save.selected;world=save.world;run={distance:0,coins:0,lives:3,speed:2.5+save.upgrades.boost*.14,jump:0,vy:0,slide:0,skill:0,invuln:0,shield:0,combo:0,comboTime:0,objects:[],particles:[],bg:0,boss:0,score:0,gem:0,shake:0};spawnT=50;state='playing';$('#home').style.display='none';$('.world-select').style.display='none';$('.footer').style.display='none';$('#hud').classList.add('active');document.querySelectorAll('.screen').forEach(e=>e.classList.remove('show'));now0=performance.now();requestAnimationFrame(loop)}function jump(){if(state!=='playing')return;if(run.jump===0){run.vy=9.7;run.jump=1;emit(90,G-4,worlds[world][6],5,1.3)}else if(run.jump===1){run.vy=8.1;run.jump=2;emit(90,G-26,heroes[hero][1],9,2)}}function slide(){if(state==='playing'){run.slide=34;emit(90,G-5,'#c7d5d6',4,1)}}function skill(){if(state!=='playing'||run.skill>0)return;run.skill=500;run.invuln=110;run.flash=12;let [name]=heroes[hero];if(hero===0){run.speed+=1.3;run.objects.forEach(o=>{if(!['coin','gem','power'].includes(o.type)&&o.x>55&&o.x<250)o.x=-100});emit(90,G-18,'#ff995d',25,5)}if(hero===1){run.objects.forEach(o=>{if(o.type==='coin'||o.type==='gem')o.x-=48});emit(90,G-20,'#b7bfff',24,3)}if(hero===2){run.speed+=.4;run.objects.forEach(o=>{if(!['coin','gem','power'].includes(o.type)&&o.x>60&&o.x<260)o.x=-100});emit(90,G-20,'#8beac9',30,4)}if(hero===3){run.invuln=240;emit(90,G-20,'#bc90e3',22,3)}if(hero===4){run.shield=240;run.lives=Math.min(3,run.lives+1);emit(90,G-20,'#ffe79c',28,3)}if(hero===5){run.objects.forEach(o=>{if(!['coin','gem','power'].includes(o.type)&&o.x<360)o.x=-100});run.score+=250;emit(90,G-20,'#a0e9ff',30,5)}toast(heroes[hero][3]+'!')}
function loop(now){if(state!=='playing')return;let dt=Math.min(34,now-now0),f=dt/16.67;now0=now;run.distance+=run.speed*.075*f;run.score+=run.speed*.4*f;run.bg+=run.speed*f;run.speed=Math.min(5.5,2.5+run.distance*.0009+save.upgrades.boost*.14);if(run.jump){run.vy-=.53*f;run.jump+=run.vy*f;if(run.jump<=0){run.jump=0;run.vy=0;emit(90,G-3,worlds[world][6],3,1)}}if(run.slide>0)run.slide-=f;if(run.skill>0)run.skill-=f;if(run.invuln>0)run.invuln-=f;if(run.shield>0)run.shield-=f;if(run.comboTime>0)run.comboTime-=f;else run.combo=0;run.boss+=f;if(run.boss>1050){run.boss=0;$('#boss').classList.add('show');toast('Something stirs behind you...');setTimeout(()=>$('#boss').classList.remove('show'),6500)}spawnT-=f;if(spawnT<=0){spawn();spawnT=Math.max(36,rand(58,100)-run.distance*.012)}if(run.shake>0)run.shake*=.78;c.save();if(run.shake>1)c.translate(rand(-run.shake,run.shake),rand(-2,2));background(now);drawObjects(dt);drawHero(90,G-18-run.jump,1,hero,run.slide>0?'slide':run.jump?'jump':'run');if(run.flash>0){c.fillStyle=heroes[hero][1]+'26';c.fillRect(0,0,W,H);run.flash--}c.restore();$('#score').textContent=String(Math.floor(run.score+run.coins*25)).padStart(5,'0');$('#runCoins').textContent=run.coins;$('#lives').textContent=Array.from({length:3},(_,i)=>i<run.lives?'♥':'♡').join(' ');$('#progress').style.width=(run.distance%1000)/10+'%';$('#skill').innerHTML=run.skill>0?'<span>⌛</span>'+Math.ceil(run.skill/60):'<span>✦</span>SKILL';$('#skill').style.opacity=run.skill>0?'.48':'1';if(run.distance%230<2)$('#hudWorld').textContent=worldName()+' / '+String(Math.floor(run.distance/230)+1).padStart(2,'0');requestAnimationFrame(loop)}

