const canvas=$('#game'),ctx=canvas.getContext('2d');let W=960,H=540,ground=425,scale=1,hero=0,world=0,state='menu',run=null,last=0,spawnTimer=50,sceneTime=0,panelTab='';
function fit(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.max(1,Math.floor(r.width*dpr));canvas.height=Math.max(1,Math.floor(r.height*dpr));scale=Math.min(canvas.width/W,canvas.height/H);ctx.setTransform(scale,0,0,scale,Math.round((canvas.width-W*scale)/2),Math.round((canvas.height-H*scale)/2))}addEventListener('resize',fit);fit();
