function renderPanel(which){const titles={heroes:'Choose Your Runner',worlds:'Pick a Sweet World',shop:'The Sugar Workshop',records:'Adventurer Journal'};$('#panelTitle').textContent=titles[which]||'Journal';let tabs=which==='shop'?['upgrades','skins']:which==='records'?['missions','achievements','high scores']:[];$('#tabs').innerHTML=tabs.map(t=>`<button class="tab ${panelTab===t?'active':''}" data-tab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('');$('#tabs').style.display=tabs.length?'flex':'none';let content='';
 if(which==='heroes'){content='<div class="grid">'+heroes.map((h,i)=>{let unlocked=save.unlockedHeroes.includes(i),selected=save.selected===i;return `<article class="card ${selected?'selected':''}"><span class="char-icon">${h.emoji}</span><h3>${h.name}</h3><p>${h.desc}</p><p><b style="color:var(--mint)">${h.skill}</b></p><button class="card-btn" data-hero="${i}" ${!unlocked?'':' '}>${selected?'Selected':unlocked?'Select':'Unlock · '+(i*75)+' ●'}</button></article>`}).join('')+'</div>'}
 if(which==='worlds'){content='<div class="grid">'+worlds.map((w,i)=>{let unlocked=save.unlockedWorlds.includes(i);return `<article class="card ${save.world===i?'selected':''}" style="background:linear-gradient(145deg,${w.sky}55,#ffffff08)"><span class="char-icon">${w.emoji}</span><h3>${w.name}</h3><p>${['A breezy first dash through the blossom trees.','Watch for slippery ice and falling icicles.','Warm winds hide chunky rolling rocks.','A midnight maze with buzzing pastry drones.','The final fiery sprint. Mind the flames!'][i]}</p><button class="card-btn" data-world="${i}">${save.world===i?'Selected':unlocked?'Travel here':'Unlock · '+(i*50)+' ●'}</button></article>`}).join('')+'</div>'}
 if(which==='shop'&&panelTab==='upgrades'){const names={boost:['Pep in Your Step','Start each run a little faster.'],magnet:['Crumb Magnet','Coins drift toward you from farther away.'],heart:['Extra Heart','Begin each run with an extra life.']};content='<div class="grid">'+Object.keys(names).map(k=>{let level=save.upgrades[k],cost=(level+1)*70;return `<article class="card"><span class="char-icon">${k==='boost'?'⚡':k==='magnet'?'🧲':'💗'}</span><h3>${names[k][0]}</h3><p>${names[k][1]}</p><div class="meter"><i style="width:${level*20}%"></i></div><p>Level ${level}/5</p><button class="card-btn" data-upgrade="${k}" ${level>=5?'disabled':''}>${level>=5?'MAXED':'Upgrade · '+cost+' ●'}</button></article>`}).join('')+'</div>'}
 if(which==='shop'&&panelTab==='skins'){content='<p style="color:#c5bfd7">A little extra sparkle for your favorite runner. Choose a palette to collect.</p><div class="grid">'+['Berry Pop','Starlight','Mint Chip','Golden Hour'].map((n,i)=>{let got=save.skins.includes(i);return `<article class="card"><span class="char-icon">${['🍓','🌟','🍃','✨'][i]}</span><h3>${n}</h3><p>Rare colorway for every runner.</p><button class="card-btn" data-skin="${i}">${got?'Owned':'Collect · '+(i+1)*5+' ◆'}</button></article>`}).join('')+'</div>'}
 if(which==='records'&&panelTab==='missions'){const ms=[['runs','Finish 3 runs',save.missions.runs,3,'🏃'],['coins','Collect 100 coins',save.missions.coins,100,'🪙'],['distance','Run 2,000m',Math.floor(save.missions.distance),2000,'📏']];content='<div class="grid">'+ms.map(([key,label,val,goal,ico])=>{let done=save.achievements.includes('mission-'+key);return `<article class="card"><span class="char-icon">${ico}</span><h3>${label}</h3><div class="meter"><i style="width:${Math.min(100,val/goal*100)}%"></i></div><p>${Math.min(val,goal)} / ${goal} · Reward: 40 ●</p><button class="card-btn" data-mission="${key}" ${val<goal||done?'disabled':''}>${done?'Claimed':val>=goal?'Claim reward':'In progress'}</button></article>`}).join('')+'</div>'}
