function hideModal(){$('#modalBack').classList.remove('show')}
function startRun(){hero=save.selected;world=save.world;run={distance:0,coins:0,gems:0,lives:Math.min(4,3+save.upgrades.heart),speed:3.3+jumpBoost(),height:0,vy:0,jumps:0,slide:0,skill:0,invuln:0,shield:0,combo:0,comboTime:0,objects:[],particles:[],bg:0,score:0,shake:0,boss:0,bossActive:0,dash:0};spawnTimer=44;state='playing';$('#home').classList.remove('active');$('#panelScreen').classList.remove('active');$('#hud').classList.add('active');hideModal();last=performance.now();requestAnimationFrame(frame)}
function jumpBoost(){return save.upgrades.boost*.14}
