?'♥':'♡').join(' ');$('#progress').style.width=(run.distance%1000)/10+'%';$('#hudWorld').textContent=worlds[world].name+' · '+String(Math.floor(run.distance/1000)+1).padStart(2,'0');$('#skillBtn').innerHTML=run.skill>0?`⌛<small>${Math.ceil(run.skill/60)}s</small>`:'✦<small>SKILL</small>';$('#skillBtn').style.opacity=run.skill>0?'.5':'1';requestAnimationFrame(frame)}
